cd /home/milos/Desktop/tests_lib/featbit
mkdir -p stack/nginx
cat > stack/nginx/featbit.conf <<'NGINX'
server {
  listen 8080;
  server_name _;

  # the management API
  location ~* ^/api/v[0-9]+/ {
    proxy_pass http://api-server:5000;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
  }

  # the SDK-facing API on the evaluation server
  location ^~ /api/public/ {
    proxy_pass http://evaluation-server:5100;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
  }

  # the websocket stream. Without the two upgrade headers the SDKs connect and hang.
  location ^~ /streaming {
    proxy_pass http://evaluation-server:5100;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
    proxy_set_header Host $host;
    proxy_read_timeout 3600s;
    proxy_send_timeout 3600s;
  }

  # everything else is the console
  location / {
    proxy_pass http://ui:80;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
  }
}
NGINX
echo "wrote nginx conf:"; wc -l stack/nginx/featbit.conf

cd /home/milos/Desktop/tests_lib/featbit/sql
cp schema.sql seed.sql
cat >> seed.sql <<'EOF'

-- ================= redu: close the published-credential window =================
-- The seed above creates test@featbit.com with a password hash committed to the public
-- repo and a plaintext password printed in upstream's install docs. Rename it HERE, in
-- the same psql run (and the same transaction) that creates it, so there is never a
-- committed moment where the published address exists.
UPDATE users SET email = '«REDACTED:env:013044ef»' WHERE email = 'test@featbit.com';

DO $redu$
DECLARE
    leftover INT;
    renamed  INT;
BEGIN
    SELECT count(*) INTO leftover FROM users WHERE email = 'test@featbit.com';
    SELECT count(*) INTO renamed  FROM users WHERE email = '«REDACTED:env:013044ef»';
    IF leftover > 0 THEN
        RAISE EXCEPTION 'refusing to commit: test@featbit.com still present';
    END IF;
    IF renamed <> 1 THEN
        RAISE EXCEPTION 'refusing to commit: expected exactly 1 renamed admin, found %', renamed;
    END IF;
    RAISE NOTICE 'redu: admin renamed, published address absent';
END
$redu$;
EOF
echo "seed.sql: $(wc -l < seed.sql) lines, $(wc -c < seed.sql) bytes"
echo "--- tail:"; tail -5 seed.sql

